SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS date, COUNT(id) AS applyCount, SUM(CASE WHEN refund_status = '3' THEN 1 ELSE 0 END) AS completeCount FROM order_refund
AND create_time >= #{req.startTime}
AND create_time <= #{req.endTime}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d') ORDER BY DATE_FORMAT(create_time, '%Y-%m-%d') ASC
